package main

import "fmt"

// minMax menggunakan named return values
func minMax(nums []int) (min, max int) {
	min = nums[0]
	max = nums[0]
	for _, n := range nums {
		if n < min {
			min = n
		}
		if n > max {
			max = n
		}
	}
	return // naked return
}

// clamp menggunakan named return
func clamp(val, lo, hi int) (result int, wasClamped bool) {
	switch {
	case val < lo:
		result = lo
		wasClamped = true
	case val > hi:
		result = hi
		wasClamped = true
	default:
		result = val
	}
	return
}

func main() {
	nums := []int{5, 2, 8, 1, 9, 3}
	min, max := minMax(nums)
	fmt.Printf("Min: %d, Max: %d\n", min, max)

	r1, c1 := clamp(150, 0, 100)
	fmt.Printf("clamp(150,0,100) = %d, clamped=%t\n", r1, c1)

	r2, c2 := clamp(50, 0, 100)
	fmt.Printf("clamp(50,0,100)  = %d, clamped=%t\n", r2, c2)
}
